import * as T from './vendor/three.module.js';
import {roadWidth,END_Z} from './world-engine.js';
export class WorldView{
 constructor(canvas,game){this.game=game;this.canvas=canvas;this.renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.7));this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.1;
 this.scene=new T.Scene();this.scene.background=new T.Color('#b8e3f6');this.scene.fog=new T.Fog('#b8e3f6',1500,3200);this.camera=new T.PerspectiveCamera(54,1,10,6000);this.scene.add(new T.HemisphereLight(0xe4ddff,0x43334b,2.5));const sun=new T.DirectionalLight(0xffdfb4,3.1);sun.position.set(-450,1100,600);this.scene.add(sun);const blue=new T.DirectionalLight(0x918cff,1.1);blue.position.set(450,450,-200);this.scene.add(blue);
 this.materials=new Map();this.boxGeometry=new T.BoxGeometry(1,1,1);this.sphere=new T.IcosahedronGeometry(1,0);this.enemies=new Map();this.barrels=new Map();this.boxes=new Map();this.gates=new Map();this.fx=new Map();this.arcLines=new Map();this.dummy=new T.Object3D();
 this.enemyTexture=new T.TextureLoader().load('assets/golem.webp');this.enemyTexture.colorSpace=T.SRGBColorSpace;
 this.buildMap();this.batchScenery();this.tank=this.buildTank();this.scene.add(this.tank);this.bullets=new T.InstancedMesh(new T.BoxGeometry(5,5,30),new T.MeshBasicMaterial({color:0xffe6b0}),1024);this.bullets.frustumCulled=false;this.scene.add(this.bullets);
 this.aimLine=new T.Line(new T.BufferGeometry(),new T.LineDashedMaterial({color:0xffe0a0,dashSize:20,gapSize:14,transparent:true,opacity:.65}));this.scene.add(this.aimLine);this.warning=this.box(1,2,1,0xff334f);this.warning.material=new T.MeshBasicMaterial({color:0xff334f,transparent:true,opacity:.32});this.scene.add(this.warning);this.resize();}
 mat(color){if(!this.materials.has(color))this.materials.set(color,new T.MeshStandardMaterial({color,roughness:.78,metalness:.12}));return this.materials.get(color);}
 box(w,h,d,color){const m=new T.Mesh(this.boxGeometry,this.mat(color));m.scale.set(w,h,d);return m;}
 addBox(x,y,z,w,h,d,color){const m=this.box(w,h,d,color);m.position.set(x,y,z);this.scene.add(m);return m;}
 buildMap(){
 for(let z=-150;z<END_Z+300;z+=150){const width=roadWidth(z+75),palette=z<1150?[0xa7dca4,0xb5e8b1]:z<1750?[0xbcb0e2,0xd1c0e9]:z<3100?[0xf2d299,0xffdfa8]:z<3850?[0xadbfe8,0xc4d0ed]:[0xe5b5cf,0xf3c8de];const columns=Math.ceil(width*2/145),size=width*2/columns;for(let c=0;c<columns;c++){this.addBox(-width+size*(c+.5),-12,z+75,size-3,22,147,palette[(c+Math.floor(z/150))&1]);}for(const sign of[-1,1]){this.addBox(sign*(width+18),24,z+75,26,65,149,0x647ca7);if(Math.round(z/150)%3===0){this.addBox(sign*(width+30),72,z+75,70,150,70,0x91a5d5);this.addBox(sign*(width+30),154,z+75,85,18,85,0x8d7c91);const crystal=new T.Mesh(new T.IcosahedronGeometry(14),new T.MeshBasicMaterial({color:z>3850?0xff8d78:0xcc94ff}));crystal.position.set(sign*(width+30),185,z+75);this.scene.add(crystal);}}}
 const abyss=this.box(5000,20,7500,0x67bad0);abyss.position.set(0,-230,2200);this.scene.add(abyss);
 for(const w of this.game.walls){this.addBox(w.x,w.h/2,w.z,w.w,w.h,w.d,0x90a3ce);this.addBox(w.x,w.h+6,w.z,w.w+12,12,w.d+12,0x91809b);for(let i=-1;i<=1;i++)this.addBox(w.x+i*w.w/3,w.h+20,w.z,w.w/5,22,w.d+4,0x777089);}
 for(const b of this.game.barrels){const group=new T.Group();const barrel=new T.Mesh(new T.CylinderGeometry(23,25,50,10),this.mat(0x966148));barrel.position.y=25;group.add(barrel);for(const y of[10,40]){const band=new T.Mesh(new T.TorusGeometry(24,2.5,4,12),this.mat(0xcca467));band.rotation.x=Math.PI/2;band.position.y=y;group.add(band);}const core=new T.Mesh(new T.IcosahedronGeometry(11),new T.MeshBasicMaterial({color:0xffab56}));core.position.y=53;group.add(core);group.position.set(b.x,0,b.z);this.scene.add(group);this.barrels.set(b.id,group);}
 for(const b of this.game.boxes){const group=new T.Group();const color=b.type==='heal'?0x65dcae:0xeabc68;const base=this.box(55,42,46,0x4c405a);base.position.y=21;group.add(base);for(const [w,h,d]of[[13,50,50],[62,12,50]]){const bar=this.box(w,h,d,color);bar.position.y=23;group.add(bar);}group.position.set(b.x,0,b.z);this.scene.add(group);this.boxes.set(b.id,group);}
 for(const g of this.game.gates){const group=new T.Group(),width=roadWidth(g.z)-38;for(const x of[-width,0,width]){const post=this.box(20,110,22,0xb6a3d1);post.position.set(x,55,0);group.add(post);}for(const s of[-1,1]){const portal=new T.Mesh(new T.PlaneGeometry(width-15,90),new T.MeshBasicMaterial({color:0x8db8ff,transparent:true,opacity:.19,side:T.DoubleSide,depthWrite:false}));portal.position.set(s*width/2,50,0);group.add(portal);const lintel=this.box(width-8,12,25,0x99baff);lintel.position.set(s*width/2,108,0);group.add(lintel);}group.position.z=g.z;this.scene.add(group);this.gates.set(g.id,group);}
 const finish=this.box(760,10,90,0xc1a260);finish.position.set(0,1,END_Z);this.scene.add(finish);
 this.lockDoor=new T.Group();for(let x=-420;x<=420;x+=60){const m=this.box(15,140,15,0xd48397);m.position.set(x,70,0);this.lockDoor.add(m);}this.scene.add(this.lockDoor);
 }
 batchScenery(){const groups=new Map();for(const obj of [...this.scene.children]){if(obj.isMesh&&obj.geometry===this.boxGeometry){const list=groups.get(obj.material)||[];list.push(obj);groups.set(obj.material,list);}}for(const [material,list]of groups){const batch=new T.InstancedMesh(this.boxGeometry,material,list.length);list.forEach((obj,i)=>{obj.updateMatrix();batch.setMatrixAt(i,obj.matrix);this.scene.remove(obj);});batch.instanceMatrix.needsUpdate=true;batch.computeBoundingSphere();this.scene.add(batch);}}
 buildTank(){const body=new T.Group();for(const x of[-42,42]){const track=this.box(25,25,108,0x242638);track.position.set(x,18,0);body.add(track);for(let z=-36;z<=36;z+=18){const tread=this.box(28,5,8,0x777186);tread.position.set(x,32,z);body.add(tread);}}const hull=this.box(68,30,88,0x36c8cf);hull.position.y=30;body.add(hull);const rim=this.box(72,6,88,0xcfac70);rim.position.y=45;body.add(rim);this.turret=new T.Group();this.turret.position.y=48;const dome=new T.Mesh(new T.CylinderGeometry(25,29,18,12),this.mat(0xffc751));this.turret.add(dome);const barrel=new T.Mesh(new T.CylinderGeometry(7,9,70,10),this.mat(0xddb577));barrel.rotation.x=Math.PI/2;barrel.position.set(0,8,40);this.turret.add(barrel);this.gem=new T.Mesh(new T.IcosahedronGeometry(15),new T.MeshStandardMaterial({color:0xd4a5ff,emissive:0x7c36cb,emissiveIntensity:1}));this.gem.position.set(0,25,0);this.turret.add(this.gem);body.add(this.turret);return body;}
 enemyObject(e){const group=new T.Group();const sprite=new T.Sprite(new T.SpriteMaterial({map:this.enemyTexture,color:e.color,transparent:true,depthWrite:false}));sprite.scale.set(e.r*3.5,e.r*3.5,1);sprite.position.y=e.r*1.65;group.add(sprite);group.userData.sprite=sprite;const shadow=new T.Mesh(new T.CircleGeometry(e.r*1.1,16),new T.MeshBasicMaterial({color:0x0b0818,transparent:true,opacity:.3,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=2;group.add(shadow);if(e.type==='shield'){const shield=this.box(e.r*1.8,e.r*2,8,0x73cadd);shield.position.set(0,e.r,e.r);group.add(shield);group.userData.shield=shield;}if(e.type==='splitter'){const gem=new T.Mesh(this.sphere,new T.MeshBasicMaterial({color:0xb2ff80}));gem.scale.setScalar(8);gem.position.y=e.r*3.2;group.add(gem);}this.scene.add(group);return group;}
 project(x,z,y=0){const v=new T.Vector3(-x,y,z).project(this.camera);return {x:(v.x+1)/2,y:(1-v.y)/2,visible:v.z<1&&v.z>-1};}
 groundAt(x,y){const ray=new T.Raycaster();ray.setFromCamera(new T.Vector2(x*2-1,1-y*2),this.camera);const point=new T.Vector3();return ray.ray.intersectPlane(new T.Plane(new T.Vector3(0,1,0),0),point)?{x:-point.x,z:point.z}:null;}
 resize(){const b=this.canvas.getBoundingClientRect();this.renderer.setSize(b.width,b.height,false);this.camera.aspect=b.width/b.height;this.camera.updateProjectionMatrix();}
 render(){const g=this.game,p=g.player;this.scene.scale.x=-1;this.camera.position.set(-g.camera.x,1320,g.camera.z-1120);this.camera.lookAt(-g.camera.x*.85,0,g.camera.z+280);this.tank.position.set(p.x,0,p.z);this.turret.rotation.y=p.angle;this.gem.rotation.y=g.time*1.3;this.gem.material.emissiveIntensity=g.jam>0?.1:1+(g.fireClock<.06?1.5:0);
 const ids=new Set();for(const e of g.enemies){ids.add(e.id);let obj=this.enemies.get(e.id);if(!obj){obj=this.enemyObject(e);this.enemies.set(e.id,obj);}obj.position.set(e.x,Math.sin(e.t*8+e.id)*2,e.z);obj.userData.sprite.material.color.setHex(e.hit>0?0xffffff:e.color);if(obj.userData.shield){obj.userData.shield.position.set(Math.sin(e.angle)*e.r,e.r,Math.cos(e.angle)*e.r);obj.userData.shield.rotation.y=e.angle;}}for(const[id,obj]of this.enemies)if(!ids.has(id)){this.scene.remove(obj);obj.traverse(child=>{if(child.geometry&&child.geometry!==this.boxGeometry&&child.geometry!==this.sphere)child.geometry.dispose();if(child.material&&![...this.materials.values()].includes(child.material))child.material.dispose();});this.enemies.delete(id);}
 this.bullets.count=Math.min(1024,g.shots.length);g.shots.slice(0,1024).forEach((b,i)=>{this.dummy.position.set(b.x,38,b.z);this.dummy.rotation.set(0,Math.atan2(b.vx,b.vz),0);this.dummy.scale.set(1,1,1);this.dummy.updateMatrix();this.bullets.setMatrixAt(i,this.dummy.matrix);});this.bullets.instanceMatrix.needsUpdate=true;
 for(const b of g.barrels)this.barrels.get(b.id).visible=b.hp>0;for(const b of g.boxes){const obj=this.boxes.get(b.id);obj.visible=!b.taken;obj.position.y=3+Math.sin(g.time*2)*3;}for(const gate of g.gates)this.gates.get(gate.id).visible=!gate.resolved;
 const lock=g.currentLock();this.lockDoor.visible=!!lock;if(lock)this.lockDoor.position.z=(g.gates[lock.id+1]?.z??4100)-140;
 const liveFx=new Set();for(const e of g.effects){liveFx.add(e.id);let obj=this.fx.get(e.id);if(!obj){obj=new T.Group();if(e.kind==='shock'){const ring=new T.Mesh(new T.TorusGeometry(1, .018,4,48),new T.MeshBasicMaterial({color:e.color,transparent:true}));ring.rotation.x=Math.PI/2;obj.add(ring);}else{for(let i=0;i<Math.min(e.count,18);i++){const m=new T.Mesh(this.sphere,this.mat(e.color));m.scale.setScalar(4+i%4);obj.add(m);}}this.scene.add(obj);this.fx.set(e.id,obj);}obj.position.set(e.x,8,e.z);const t=1-e.life/e.max;if(e.kind==='shock'){obj.children[0].scale.setScalar(20+t*430);obj.children[0].material.opacity=1-t;}else obj.children.forEach((m,i)=>{const a=i*2.399+e.id;m.position.set(Math.cos(a)*t*100,Math.sin(t*Math.PI)*55,Math.sin(a)*t*100);m.scale.setScalar((4+i%4)*(1-t));});}for(const[id,obj]of this.fx)if(!liveFx.has(id)){this.scene.remove(obj);obj.traverse(child=>{if(child.geometry&&child.geometry!==this.sphere){child.geometry.dispose();child.material.dispose();}});this.fx.delete(id);}
 const arcIds=new Set();for(const a of g.arcs){arcIds.add(a.id);if(!this.arcLines.has(a.id)){const line=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3(a.x,45,a.z),new T.Vector3((a.x+a.tx)/2+15,65,(a.z+a.tz)/2),new T.Vector3(a.tx,45,a.tz)]),new T.LineBasicMaterial({color:0xe0a9ff}));this.scene.add(line);this.arcLines.set(a.id,line);}}for(const[id,line]of this.arcLines)if(!arcIds.has(id)){this.scene.remove(line);line.geometry.dispose();line.material.dispose();this.arcLines.delete(id);}
 this.aimLine.visible=!!g.manualAim;if(g.manualAim){this.aimLine.geometry.dispose();this.aimLine.geometry=new T.BufferGeometry().setFromPoints([new T.Vector3(p.x,30,p.z),new T.Vector3(g.manualAim.x,30,g.manualAim.z)]);this.aimLine.computeLineDistances();}
 const boss=g.boss;this.warning.visible=!!boss&&!boss.dead&&['windup','charge'].includes(boss.phase);if(this.warning.visible){const t=boss.target,dx=t.x-boss.x,dz=t.z-boss.z,l=Math.max(400,Math.hypot(dx,dz));this.warning.position.set(boss.x+dx*.5,3,boss.z+dz*.5);this.warning.scale.set(135,2,l+300);this.warning.rotation.y=Math.atan2(dx,dz);}
 this.renderer.render(this.scene,this.camera);
 }
 dispose(){this.scene.traverse(obj=>{if(obj.geometry&&obj.geometry!==this.boxGeometry&&obj.geometry!==this.sphere)obj.geometry.dispose();if(obj.material){const list=Array.isArray(obj.material)?obj.material:[obj.material];for(const mat of list)mat.dispose();}});this.boxGeometry.dispose();this.sphere.dispose();this.enemyTexture.dispose();this.renderer.dispose();}
}
